export const WHITE_PRODUCTS: WhiteProduct[] = [
  {key: 1, slug: 'lnyanoy-kostyum-s-yubkoy-maksi', en: 'Linen Maxi Suit', ru: 'Льняной костюм с юбкой макси', cat: 'tailoring', price: 7500, descEn: 'A sleeveless linen vest and a floor-skimming maxi skirt, cut for summer ease. Natural buttons, a defined waist, unlined.', descRu: 'Льняной жилет без рукавов и юбка макси в пол — летняя лёгкость. Натуральные пуговицы, подчёркнутая талия, без подклада.', storyEn: 'A two-piece that holds its shape through the day and stops asking to be pressed after the first hour. The sleeveless vest is cut close — darts draw the waist in, natural buttons meet edge to edge, the armhole is open enough to take a tee underneath or nothing at all. The maxi skirt falls from the hip in a clean wedge, long enough to cover the ankle with the stride left free. The linen is a heavier weave with visible texture: it does not go sheer in sunlight and keeps its colour through washing. Unlined, so it stays breathable in heat. Wear it whole, or apart — the vest sits on jeans, the skirt takes any top.', storyRu: 'Костюм из двух частей, который держит форму весь день и не просит глажки после первого часа. Жилет без рукавов скроен по фигуре: вытачки собирают талию, натуральные пуговицы застёгиваются встык, пройма открытая — под него легко уходит футболка или ничего. Юбка макси падает от бедра ровным клином, длина закрывает щиколотку, шаг свободный. Лён взят плотный, с характерной фактурой: он не просвечивает на солнце и держит цвет после стирки. Без подклада — костюм остаётся дышащим в жару. Носится целиком как комплект и по отдельности: жилет садится на джинсы, юбка живёт с любым верхом.', compositionEn: 'Linen 30%, cotton 30%, viscose 20%, polyester 20%', compositionRu: 'Лён 30%, хлопок 30%, вискоза 20%, полиэстер 20%', careEn: 'Machine wash cold, gentle', careRu: 'Деликатная стирка в холодной воде', colors: [{...IVORY, nm: 1008989269}, {...SKYBLUE, nm: 1008989273, image: '/images/white/products/p-1008989269-skyblue-X.jpg', gallery: ['/images/white/products/p-1008989269-skyblue-b-X.jpg', '/images/white/products/p-1008989269-skyblue-3-X.jpg', '/images/white/products/p-1008989269-skyblue-s-X.jpg', '/images/white/products/p-1008989269-skyblue-d-X.jpg']}, {...YELLOW, nm: 1008989272, image: '/images/white/products/p-1008989269-yellow-X.jpg', gallery: ['/images/white/products/p-1008989269-yellow-b-X.jpg', '/images/white/products/p-1008989269-yellow-3-X.jpg', '/images/white/products/p-1008989269-yellow-s-X.jpg', '/images/white/products/p-1008989269-yellow-d-X.jpg']}, {...GREEN, nm: 1008989270, image: '/images/white/products/p-1008989269-green-X.jpg', gallery: ['/images/white/products/p-1008989269-green-b-X.jpg', '/images/white/products/p-1008989269-green-3-X.jpg', '/images/white/products/p-1008989269-green-s-X.jpg', '/images/white/products/p-1008989269-green-d-X.jpg']}, {...ORANGE, nm: 1008989274, image: '/images/white/products/p-1008989269-orange-X.jpg', gallery: ['/images/white/products/p-1008989269-orange-b-X.jpg', '/images/white/products/p-1008989269-orange-3-X.jpg', '/images/white/products/p-1008989269-orange-s-X.jpg', '/images/white/products/p-1008989269-orange-d-X.jpg']}, {...ROSE, nm: 1008989271, image: '/images/white/products/p-1008989269-rose-X.jpg', gallery: ['/images/white/products/p-1008989269-rose-b-X.jpg', '/images/white/products/p-1008989269-rose-3-X.jpg', '/images/white/products/p-1008989269-rose-s-X.jpg', '/images/white/products/p-1008989269-rose-d-X.jpg']}, {...BROWN, nm: 1008989268, image: '/images/white/products/p-1008989269-brown-X.jpg', gallery: ['/images/white/products/p-1008989269-brown-b-X.jpg', '/images/white/products/p-1008989269-brown-3-X.jpg', '/images/white/products/p-1008989269-brown-s-X.jpg', '/images/white/products/p-1008989269-brown-d-X.jpg']}], image: '/images/white/products/p-1008989269-X.jpg', nm: 1008989269, gallery: ['/images/white/products/p-1008989269-b-X.jpg', '/images/white/products/p-1008989269-3-X.jpg', '/images/white/products/p-1008989269-s-X.jpg', '/images/white/products/p-1008989269-d-X.jpg']},
  {key: 2, slug: 'palto-pidzhak-pritalennoe', en: 'Fitted Blazer Coat', ru: 'Пальто-пиджак приталенное', cat: 'outerwear', price: 23000, descEn: 'A demi-season coat cut like a blazer — clean collarless shoulders and a sculpted, buttoned waist. Fully lined.', descRu: 'Демисезонное пальто с кроем пиджака — чистые плечи без воротника и скульптурная талия на пуговицах. На подкладе.', storyEn: 'A demi-season coat built on blazer logic: a clean shoulder, no collar, an open neckline. The waist is drawn in and buttoned, so the silhouette sculpts rather than falls straight. It ends mid-thigh with a full sleeve. The wool blend keeps its shape on the hanger and does not crease at the elbow after a day in the car. Fully lined — it goes over a sweater without fighting you and comes off in one motion. A coat for the city between +5 and +15: fine knitwear or a shirt underneath, nothing needed on top.', storyRu: 'Демисезонное пальто, скроенное по логике пиджака: плечо чистое, без воротника, линия горловины открытая. Талия собрана и застёгнута на пуговицы — силуэт получается скульптурный, а не прямой. Длина до середины бедра, рукав полный. Шерстяная смесь держит форму на весу и не мнётся в рукаве после дня в машине. Полностью на подкладе: надевается поверх свитера без сопротивления, снимается одним движением. Это пальто для города в +5…+15 — под него уходит и тонкий трикотаж, и рубашка, а сверху ничего не нужно.', compositionEn: 'Wool 60%, cashmere 20%, polyester 15%, viscose 5%', compositionRu: 'Шерсть 60%, кашемир 20%, полиэстер 15%, вискоза 5%', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [{...IVORY, nm: 795522033}, {...GREY, nm: 795528752, image: '/images/white/products/p-795522033-grey-Q.jpg', gallery: ['/images/white/products/p-795522033-grey-b-Q.jpg', '/images/white/products/p-795522033-grey-3-Q.jpg', '/images/white/products/p-795522033-grey-s-Q.jpg', '/images/white/products/p-795522033-grey-d-T.jpg']}, {...BROWN, nm: 795327858, image: '/images/white/products/p-795522033-brown-Q.jpg', gallery: ['/images/white/products/p-795522033-brown-b-Q.jpg', '/images/white/products/p-795522033-brown-3-Q.jpg', '/images/white/products/p-795522033-brown-s-Q.jpg', '/images/white/products/p-795522033-brown-d-T.jpg']}], image: '/images/white/products/p-795522033-Q.jpg', nm: 795522033, gallery: ['/images/white/products/p-795522033-b-Q.jpg', '/images/white/products/p-795522033-3-Q.jpg', '/images/white/products/p-795522033-s-Q.jpg', '/images/white/products/p-795522033-d-Q.jpg']},
  {key: 3, slug: 'zhilet-kostyumnyy-s-baskoy', en: 'Peplum Suit Vest', ru: 'Жилет костюмный с баской', cat: 'tailoring', price: 7500, descEn: 'A classic tailored vest with a peplum flare and a buttoned front. Nipped at the waist, sharp over anything.', descRu: 'Классический костюмный жилет с баской и застёжкой на пуговицы. Приталенный, острый поверх чего угодно.', storyEn: 'A tailored vest where the work sits in the cut rather than the trim. The peplum leaves the waist in a soft wave and covers the hip, so the line reads as an hourglass even over straight trousers. The front buttons through, the back is whole, the armhole is high — it does not ride up when you raise your arms. A dense cotton blend with a matte surface that holds a sharp edge. Wear it as a top in its own right: matching trousers make it a suit, jeans make it a contrast, over a shirt it reads as the third piece.', storyRu: 'Классический костюмный жилет, у которого работа сделана в крое, а не в отделке. Баска отходит от талии мягкой волной и прикрывает бедро — силуэт читается как песочные часы даже поверх прямых брюк. Перед застёгивается на пуговицы, спина цельная, пройма высокая: жилет не съезжает, когда поднимаешь руки. Хлопковая смесь плотная, с матовой поверхностью, держит острые линии. Носится как самостоятельный верх — с брюками в тон получается костюм, с джинсами выходит контраст, поверх рубашки читается как жилет от тройки.', compositionEn: 'Suiting: polyester 55%, viscose 40%, elastane 5%', compositionRu: 'Костюмная ткань: полиэстер 55%, вискоза 40%, эластан 5%', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [{...BROWN, nm: 962827637}, {...BLACK, nm: 962827638, image: '/images/white/products/p-962827637-black-B.jpg', gallery: ['/images/white/products/p-962827637-black-b-F.jpg', '/images/white/products/p-962827637-black-3-F.jpg', '/images/white/products/p-962827637-black-s-F.jpg', '/images/white/products/p-962827637-black-d-F.jpg']}, {...WHITE_COL, nm: 962827636, image: '/images/white/products/p-962827637-white-B.jpg', gallery: ['/images/white/products/p-962827637-white-b-F.jpg', '/images/white/products/p-962827637-white-3-F.jpg', '/images/white/products/p-962827637-white-s-F.jpg', '/images/white/products/p-962827637-white-d-F.jpg']}, {...YELLOW, nm: 962827639, image: '/images/white/products/p-962827637-yellow-B.jpg', gallery: ['/images/white/products/p-962827637-yellow-b-F.jpg', '/images/white/products/p-962827637-yellow-3-F.jpg', '/images/white/products/p-962827637-yellow-s-F.jpg', '/images/white/products/p-962827637-yellow-d-F.jpg']}, {...ROSE, nm: 962827640, image: '/images/white/products/p-962827637-pink-B.jpg', gallery: ['/images/white/products/p-962827637-pink-b-F.jpg', '/images/white/products/p-962827637-pink-3-F.jpg', '/images/white/products/p-962827637-pink-s-F.jpg', '/images/white/products/p-962827637-pink-d-F.jpg']}, {...GREY, nm: 1224726113, image: '/images/white/products/p-962827637-grey-B.jpg', gallery: ['/images/white/products/p-962827637-grey-b-F.jpg', '/images/white/products/p-962827637-grey-3-F.jpg', '/images/white/products/p-962827637-grey-s-F.jpg', '/images/white/products/p-962827637-grey-d-F.jpg']}], image: '/images/white/products/p-962827637-B.jpg', nm: 962827637, gallery: ['/images/white/products/p-962827637-b-F.jpg', '/images/white/products/p-962827637-3-F.jpg', '/images/white/products/p-962827637-s-F.jpg', '/images/white/products/p-962827637-d-F.jpg']},
  {key: 4, slug: 'svitshot-s-bantikami', en: 'Bow Sweatshirt', ru: 'Свитшот с бантиками', cat: 'knitwear', price: 4500, descEn: 'An oversized cotton sweatshirt softened with bow details. Dropped shoulders, ribbed trims, soft cotton.', descRu: 'Оверсайз-свитшот из хлопка, смягчённый бантиками. Приспущенное плечо, рубчатые края, мягкий хлопок.', storyEn: 'A relaxed sweatshirt softened with bows along the sleeve. The shoulder is dropped and the volume is there, but it does not drag: ribbed cuffs and hem gather the shape and keep it from spreading after washing. A cotton blend with a soft inside face — it goes on bare skin without scratching. It covers the waistband, which is why it sits equally well with a balloon skirt, straight jeans or high-rise trousers. The bows are stitched by hand and do not catch under a coat.', storyRu: 'Свитшот свободного кроя, смягчённый бантиками по линии рукава. Плечо приспущено, объём есть, но он не тянет вниз: рубчатые манжеты и низ собирают форму и не дают вещи расползтись после стирки. Хлопковая смесь с мягкой изнанкой — надевается на голое тело без раздражения. Длина закрывает пояс, поэтому свитшот одинаково живёт с юбкой-баллон, прямыми джинсами и брюками с высокой посадкой. Лента продета через ткань и завязана поверх, поэтому рукав остаётся закрытым.', compositionEn: 'Cotton 70%, polyester 30%', compositionRu: 'Хлопок 70%, полиэстер 30%', careEn: 'Machine wash cold', careRu: 'Машинная стирка в холодной воде', colors: [{...BLACK, nm: 442574310}, {...WHITE_COL, nm: 442577046, image: '/images/white/products/p-442577291-white-I.jpg', gallery: ['/images/white/products/p-442577291-white-c-I.jpg', '/images/white/products/p-442577291-white-3-I.jpg', '/images/white/products/p-442577291-white-b-I.jpg', '/images/white/products/p-442577291-white-s-I.jpg', '/images/white/products/p-442577291-white-d-M.jpg']}, {...GREY, nm: 442577291, image: '/images/white/products/p-442577291-grey-I.jpg', gallery: ['/images/white/products/p-442577291-grey-c-I.jpg', '/images/white/products/p-442577291-grey-3-I.jpg', '/images/white/products/p-442577291-grey-b-I.jpg', '/images/white/products/p-442577291-grey-s-I.jpg', '/images/white/products/p-442577291-grey-d-M.jpg']}], image: '/images/white/products/p-442577291-I.jpg', nm: 442574310, gallery: ['/images/white/products/p-442577291-c-I.jpg', '/images/white/products/p-442577291-3-I.jpg', '/images/white/products/p-442577291-b-I.jpg', '/images/white/products/p-442577291-s-I.jpg', '/images/white/products/p-442577291-d-M.jpg']},
  {key: 5, slug: 'yubka-karandash-s-kruzhevnym-podyubnikom', en: 'Lace-Hem Pencil Skirt', ru: 'Юбка карандаш с кружевным подъюбником', cat: 'skirts', price: 25000, season: 'aw26', descEn: 'A long pencil skirt with a lace underskirt showing at the hem. Office discipline, with one thing left undone.', descRu: 'Длинная юбка карандаш с кружевным подъюбником, который выходит из-под низа. Офисная дисциплина с одной незастёгнутой деталью.', storyEn: 'A pencil skirt cut long — the hem falls below the calf, where a shorter one would stop at the knee and ask to be pulled down all day. A wide waistband sits high and holds; the front is flat, the back takes a vent so the stride is not shortened. The lace underskirt is stitched in, not layered on, and shows a hand’s width below the hem: from the front it reads as a finish, from behind as the whole point. The cloth is a dense polyester-viscose with elastane — it holds a crease, does not shine at the seat and gives when you sit down. It takes a shirt tucked in and a knit left out.', storyRu: 'Юбка карандаш удлинённого кроя: низ падает ниже середины голени, тогда как короткая садилась бы на колено и весь день просила бы себя одёрнуть. Широкий пояс стоит высоко и держит, передняя половина идёт гладко, сзади заложена шлица — шаг не укорачивается. Кружевной подъюбник втачан, а не надет сверху, и выходит на ширину ладони из-под низа: спереди читается как отделка, со спины — как весь смысл вещи. Полотно плотное, полиэстер с вискозой и эластаном: держит складку, не лоснится на посадке и тянется, когда садишься. Берёт заправленную рубашку и выпущенный трикотаж.', compositionEn: 'Polyester 55%, viscose 40%, elastane 5%', compositionRu: 'Полиэстер 55%, вискоза 40%, эластан 5%', careEn: 'Machine wash cold, gentle', careRu: 'Деликатная стирка при 30°', colors: [{...BLACK, nm: 1217814224}, {...CHARCOAL, nm: 1217814225, image: '/images/white/products/p-1217814224-charcoal-D.jpg', gallery: ['/images/white/products/p-1217814224-charcoal-b-D.jpg', '/images/white/products/p-1217814224-charcoal-3-D.jpg', '/images/white/products/p-1217814224-charcoal-s-D.jpg', '/images/white/products/p-1217814224-charcoal-d-D.jpg']}, {...GREY, nm: 1217814227, image: '/images/white/products/p-1217814224-grey-D.jpg', gallery: ['/images/white/products/p-1217814224-grey-b-D.jpg', '/images/white/products/p-1217814224-grey-3-D.jpg', '/images/white/products/p-1217814224-grey-s-D.jpg', '/images/white/products/p-1217814224-grey-d-D.jpg']}, {...SAND, nm: 1217814226, image: '/images/white/products/p-1217814224-sand-D.jpg', gallery: ['/images/white/products/p-1217814224-sand-b-D.jpg', '/images/white/products/p-1217814224-sand-3-D.jpg', '/images/white/products/p-1217814224-sand-s-D.jpg', '/images/white/products/p-1217814224-sand-d-D.jpg']}, {...BROWN, nm: 1217805724, image: '/images/white/products/p-1217814224-brown-D.jpg', gallery: ['/images/white/products/p-1217814224-brown-b-D.jpg', '/images/white/products/p-1217814224-brown-3-D.jpg', '/images/white/products/p-1217814224-brown-s-D.jpg', '/images/white/products/p-1217814224-brown-d-D.jpg']}], image: '/images/white/products/p-1217814224-black-D.jpg', nm: 1217814224, gallery: ['/images/white/products/p-1217814224-black-b-D.jpg', '/images/white/products/p-1217814224-black-3-D.jpg', '/images/white/products/p-1217814224-black-s-D.jpg', '/images/white/products/p-1217814224-black-d-D.jpg']},
  {key: 6, slug: 'korset-vecherniy-s-baskoy', en: 'Peplum Evening Corset', ru: 'Корсет вечерний с баской', cat: 'dresses', price: 4000, descEn: 'A structured evening corset with a peplum hem. A boned bodice and a defined waist, made to be dressed up.', descRu: 'Структурный вечерний корсет с баской. Лиф на косточках и чёткая талия — создан для выхода.', storyEn: 'An evening corset with real structure: the boned bodice keeps the back straight and marks the waist, and the peplum spreads softly from it to cover the join with a skirt or trousers. The top edge is straight and strapless, leaving the shoulder line open. A dense cotton blend with no stretch, so the silhouette does not drift by the end of the night. It fastens at the back. This is a going-out top: a satin balloon skirt makes it evening, straight trousers make it dinner, and it disappears under a coat worn over the shoulders.', storyRu: 'Вечерний корсет со структурой: лиф на косточках держит спину прямо и очерчивает талию, баска мягко расходится от неё и прикрывает переход к юбке или брюкам. Верх ровный, без бретелей — линия плеча остаётся открытой. Хлопковая смесь плотная, не тянется, поэтому силуэт не плывёт к концу вечера. Застёжка сзади. Это верх для выхода: с атласной юбкой-баллон получается вечерний комплект, с прямыми брюками — костюм для ужина, под пальто на плечах уходит целиком.', compositionEn: 'Polyester 65%, viscose 30%, elastane 5%', compositionRu: 'Полиэстер 65%, вискоза 30%, эластан 5%', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [{...BLACK, nm: 675104410}, {...BROWN, nm: 675145713, image: '/images/white/products/p-675104410-brown-N.jpg', gallery: ['/images/white/products/p-675104410-brown-b-R.jpg', '/images/white/products/p-675104410-brown-p-R.jpg', '/images/white/products/p-675104410-brown-t-R.jpg', '/images/white/products/p-675104410-brown-d-N.jpg']}, {...IVORY, nm: 675145714, image: '/images/white/products/p-675104410-ivory-R.jpg', gallery: ['/images/white/products/p-675104410-ivory-b-R.jpg', '/images/white/products/p-675104410-ivory-p-R.jpg', '/images/white/products/p-675104410-ivory-t-R.jpg', '/images/white/products/p-675104410-ivory-d-N.jpg']}], image: '/images/white/products/p-675104410-N.jpg', nm: 675104410, gallery: ['/images/white/products/p-675104410-b-R.jpg', '/images/white/products/p-675104410-p-N.jpg', '/images/white/products/p-675104410-t-R.jpg', '/images/white/products/p-675104410-d-N.jpg']},
  {key: 7, slug: 'bryuki-alladiny', en: 'Draped Harem Trousers', ru: 'Брюки алладины', cat: 'tailoring', price: 8000, descEn: 'Softly draped harem trousers with a relaxed fall and a clean waist. Easy tailoring for every day.', descRu: 'Мягко драпированные брюки алладины со свободным силуэтом и чистой талией. Лёгкий тайлоринг на каждый день.', storyEn: 'Harem trousers with a soft drape: the cloth gathers at the waist, falls in large folds and narrows towards the ankle. The rise is high and the waistband elastic — they sit on the body with no buttons or zips and do not press after a meal. The viscose blend is weighty in the hand, so the folds lie rather than stick out. They end at the ankle bone, ready for trainers, courts or sandals. Everyday trousers that read as evening ones: a vest makes them tailoring, a t-shirt makes them rest.', storyRu: 'Брюки алладины с мягкой драпировкой: ткань собирается на поясе и уходит вниз крупными складками, а к щиколотке силуэт сужается. Посадка высокая, пояс эластичный — брюки садятся по фигуре без пуговиц и молний и не давят после еды. Вискозная смесь тяжёлая на ощупь, поэтому складки лежат, а не топорщатся. Длина до косточки: под кроссовки, лодочки и босоножки. Это брюки на каждый день, которые выглядят как вечерние — с жилетом получается тайлоринг, с футболкой отдых.', compositionEn: 'Japanese silk: cotton 40%, viscose 40%, elastane 20%', compositionRu: 'Японский шёлк: хлопок 40%, вискоза 40%, эластан 20%', careEn: 'Machine wash cold', careRu: 'Машинная стирка в холодной воде', colors: [{...SAND, nm: 962783114}, {...WHITE_COL, nm: 962783109, image: '/images/white/products/p-962783109-white-P.jpg', gallery: ['/images/white/products/p-962783109-white-b-P.jpg', '/images/white/products/p-962783109-white-3-R.jpg', '/images/white/products/p-962783109-white-s-R.jpg', '/images/white/products/p-962783109-white-d-P.jpg']}, {...BLACK, nm: 962783110, image: '/images/white/products/p-962783109-black-K.jpg', gallery: ['/images/white/products/p-962783109-black-b-P.jpg', '/images/white/products/p-962783109-black-3-K.jpg', '/images/white/products/p-962783109-black-s-K.jpg', '/images/white/products/p-962783109-black-d-K.jpg']}, {...BROWN, nm: 962783108, image: '/images/white/products/p-962783109-brown-P.jpg', gallery: ['/images/white/products/p-962783109-brown-b-L.jpg', '/images/white/products/p-962783109-brown-3-S.jpg', '/images/white/products/p-962783109-brown-s-P.jpg', '/images/white/products/p-962783109-brown-d-P.jpg']}, {...GREEN, nm: 962783111, image: '/images/white/products/p-962783109-green-R.jpg', gallery: ['/images/white/products/p-962783109-green-b-L.jpg', '/images/white/products/p-962783109-green-3-R.jpg', '/images/white/products/p-962783109-green-s-R.jpg', '/images/white/products/p-962783109-green-d-L.jpg']}, {...NAVY, nm: 962783112, image: '/images/white/products/p-962783109-navy-L.jpg', gallery: ['/images/white/products/p-962783109-navy-b-K.jpg', '/images/white/products/p-962783109-navy-3-P.jpg', '/images/white/products/p-962783109-navy-s-K.jpg', '/images/white/products/p-962783109-navy-d-K.jpg']}, {...ROSE, nm: 962783113, image: '/images/white/products/p-962783109-rose-R.jpg', gallery: ['/images/white/products/p-962783109-rose-b-L.jpg', '/images/white/products/p-962783109-rose-3-R.jpg', '/images/white/products/p-962783109-rose-s-R.jpg', '/images/white/products/p-962783109-rose-d-P.jpg']}], image: '/images/white/products/p-962783109-R.jpg', nm: 962783109, gallery: ['/images/white/products/p-962783109-b-K.jpg', '/images/white/products/p-962783109-3-R.jpg', '/images/white/products/p-962783109-s-R.jpg', '/images/white/products/p-962783109-d-K.jpg']},
  {key: 8, slug: 'yubka-ballon-atlasnaya', en: 'Satin Balloon Skirt', ru: 'Юбка баллон атласная', cat: 'skirts', price: 5000, descEn: 'A satin balloon mini with built-in shorts and a rounded volume. Matte sheen, holds its volume.', descRu: 'Атласная юбка-баллон мини с шортами и округлым объёмом. Матовый блеск, форма держит объём.', storyEn: 'A satin balloon skirt with a rounded volume: the hem is gathered inward, so it holds its shape without a petticoat. Shorts are built in — sit down, walk into the wind, stop thinking about the length. High rise, elasticated waistband. The satin is matte with a muted sheen: it catches light along the curve without looking glossy, which is what lets the skirt work in daylight. Mini length. A corset makes it evening, a sweatshirt makes it an ordinary Saturday, opaque tights take it into autumn.', storyRu: 'Атласная юбка-баллон с округлым объёмом: подол собран внутрь, и юбка держит форму сама, без подъюбника. Внутри вшиты шорты — можно садиться, идти по ветру и не думать о длине. Посадка высокая, пояс на резинке. Атлас матовый, с приглушённым блеском: он ловит свет по изгибу, но не выглядит нарядно-глянцевым, поэтому юбка работает и днём. Длина мини. С корсетом получается вечер, со свитшотом — обычная суббота, с плотными колготками уходит в осень.', compositionEn: 'Satin, polyester', compositionRu: 'Атлас, полиэстер', careEn: 'Machine wash cold', careRu: 'Машинная стирка в холодной воде', colors: [{...IVORY, nm: 371980450}, {...BLACK, nm: 371969423, image: '/images/white/products/p-371980450-black-V.jpg', gallery: ['/images/white/products/p-371980450-black-b-V.jpg', '/images/white/products/p-371980450-black-3-V.jpg', '/images/white/products/p-371980450-black-back-A.jpg', '/images/white/products/p-371980450-black-d-V.jpg']}, {...RED, nm: 379321819, image: '/images/white/products/p-371980450-red-V.jpg', gallery: ['/images/white/products/p-371980450-red-b-Z.jpg', '/images/white/products/p-371980450-red-3-V.jpg', '/images/white/products/p-371980450-red-back-A.jpg', '/images/white/products/p-371980450-red-d-Y.jpg']}, {...SKYBLUE, nm: 379315113, image: '/images/white/products/p-371980450-blue-V.jpg', gallery: ['/images/white/products/p-371980450-blue-b-V.jpg', '/images/white/products/p-371980450-blue-3-V.jpg', '/images/white/products/p-371980450-blue-back-A.jpg', '/images/white/products/p-371980450-blue-d-Y.jpg']}, {...GREY, nm: 379323231, image: '/images/white/products/p-371980450-grey-V.jpg', gallery: ['/images/white/products/p-371980450-grey-b-V.jpg', '/images/white/products/p-371980450-grey-3-V.jpg', '/images/white/products/p-371980450-grey-back-A.jpg', '/images/white/products/p-371980450-grey-d-Y.jpg']}], image: '/images/white/products/p-371980450-V.jpg', nm: 371980450, gallery: ['/images/white/products/p-371980450-b-V.jpg', '/images/white/products/p-371980450-3-V.jpg', '/images/white/products/p-371980450-back-A.jpg', '/images/white/products/p-371980450-d-Y.jpg']},
  {key: 9, slug: 'rubashka-oversayz-s-kruzhevom', en: 'Lace Oversized Shirt', ru: 'Рубашка оверсайз с кружевом', cat: 'dresses', price: 7000, descEn: 'An oversized shirt with a dramatic gathered sleeve — drawn at the wrist with a drawstring tie, a narrow lace edging showing at the cuff. Relaxed shoulders, a curved shirttail hem.', descRu: 'Оверсайз-рубашка с объёмным рукавом — кулиска с завязками у запястья, узкое кружево по краю манжеты. Свободные плечи, скруглённый низ.', storyEn: 'An oversized shirt with a dramatic sleeve: gathered at the wrist on a drawstring tie, with a narrow lace edging showing below the cuff. The shoulder is dropped, the body is generous, the hem is curved — it tucks in and hangs out equally well. Soft cotton with a lightly crumpled texture that never asks for an iron. Buttons through. Wear it over jeans, over a dress as a light layer, or as a cover-up. The sleeve is the point of this shirt, so anything worn over it is better cut loose.', storyRu: 'Рубашка свободного кроя с драматичным рукавом: у запястья он собран на кулиску с завязками, из-под манжеты выходит узкое кружево. Плечо приспущено, объём по корпусу большой, низ скруглён — рубашка одинаково хорошо заправляется и остаётся навыпуск. Хлопок мягкий, с лёгкой мятой фактурой, которая не требует утюга. Застёжка на пуговицы по всей длине. Носится на джинсы, поверх платья как лёгкий верхний слой и в качестве пляжной накидки. Рукав — главное в этой вещи, поэтому пальто поверх лучше надевать свободное.', compositionEn: 'Cotton 100%', compositionRu: 'Хлопок 100%', careEn: 'Hand wash cold', careRu: 'Ручная стирка в холодной воде', colors: [{...SAND, nm: 1113526970, en: 'Vanilla polka dot', ru: 'Ваниль в горошек'}, {...GREY, nm: 1113526968, en: 'Grey polka dot', ru: 'Серый в горошек', image: '/images/white/products/p-1113526969-grey-J.jpg', gallery: ['/images/white/products/p-1113526969-grey-c-H.jpg', '/images/white/products/p-1113526969-grey-3-H.jpg', '/images/white/products/p-1113526969-grey-b-G.jpg', '/images/white/products/p-1113526969-grey-s-H.jpg', '/images/white/products/p-1113526969-grey-d-G.jpg']}, {...BLACK, nm: 1113526969, en: 'Black pinstripe', ru: 'Чёрный в полоску', image: '/images/white/products/p-1113526969-black-J.jpg', gallery: ['/images/white/products/p-1113526969-black-c-H.jpg', '/images/white/products/p-1113526969-black-3-H.jpg', '/images/white/products/p-1113526969-black-b-G.jpg', '/images/white/products/p-1113526969-black-s-H.jpg', '/images/white/products/p-1113526969-black-d-G.jpg']}, {...ROSE, nm: 1113526971, en: 'Rose check', ru: 'Розовая клетка', image: '/images/white/products/p-1113526969-rose-J.jpg', gallery: ['/images/white/products/p-1113526969-rose-c-H.jpg', '/images/white/products/p-1113526969-rose-3-H.jpg', '/images/white/products/p-1113526969-rose-b-G.jpg', '/images/white/products/p-1113526969-rose-s-H.jpg', '/images/white/products/p-1113526969-rose-d-G.jpg']}], image: '/images/white/products/p-1113526969-H.jpg', nm: 1113526970, gallery: ['/images/white/products/p-1113526969-c-H.jpg', '/images/white/products/p-1113526969-3-H.jpg', '/images/white/products/p-1113526969-b-H.jpg', '/images/white/products/p-1113526969-s-H.jpg', '/images/white/products/p-1113526969-d-H.jpg']},
  {key: 10, slug: 'yubka-shorty-zamshevaya', en: 'Suede Skort', ru: 'Юбка-шорты замшевая', cat: 'skirts', price: 5500, descEn: 'A suede mini skort finished with a scalloped lace hem — the ease of shorts under the line of a skirt. Soft hand, elasticated waist.', descRu: 'Замшевая юбка-шорты с кружевной отделкой по низу — лёгкость шорт под линией юбки. Мягкая фактура, эластичный пояс.', storyEn: 'A suede skort: a skirt from the outside, shorts built in underneath — sit, bend, take the stairs without adjusting anything. Scalloped lace runs along the hem and softens the straight suede line. Elasticated waistband, high rise. The faux suede is soft with a velvety surface that keeps its colour and does not stretch across the hip. Mini length, A-line. Opaque tights and tall boots take it into the cold; a t-shirt keeps it summer.', storyRu: 'Замшевая юбка-шорты: снаружи читается как юбка, внутри вшиты шорты — можно садиться, наклоняться и подниматься по лестнице, не поправляя. По низу идёт кружевная отделка с фестонами, она смягчает прямой замшевый силуэт. Пояс на резинке, посадка высокая. Искусственная замша мягкая, с бархатистой поверхностью, которая держит цвет и не тянется на бедре. Длина мини, крой А-силуэт. С плотными колготками и высокими сапогами уходит в холод, с футболкой остаётся летней.', compositionEn: 'Polyester 55%, viscose 40%, elastane 5%', compositionRu: 'Полиэстер 55%, вискоза 40%, эластан 5%', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [{...IVORY, nm: 1143078000}, {...BROWN, nm: 1143067779, image: '/images/white/products/p-1143078000-brown-N.jpg', gallery: ['/images/white/products/p-1143078000-brown-b-N.jpg', '/images/white/products/p-1143078000-brown-3-N.jpg', '/images/white/products/p-1143078000-brown-s-N.jpg', '/images/white/products/p-1143078000-brown-d-N.jpg']}, {...BLACK, nm: 1143078001, image: '/images/white/products/p-1143078000-black-N.jpg', gallery: ['/images/white/products/p-1143078000-black-b-N.jpg', '/images/white/products/p-1143078000-black-3-N.jpg', '/images/white/products/p-1143078000-black-s-N.jpg', '/images/white/products/p-1143078000-black-d-N.jpg']}, {...GREEN, nm: 1143077998, image: '/images/white/products/p-1143078000-green-N.jpg', gallery: ['/images/white/products/p-1143078000-green-b-N.jpg', '/images/white/products/p-1143078000-green-3-N.jpg', '/images/white/products/p-1143078000-green-s-N.jpg', '/images/white/products/p-1143078000-green-d-N.jpg']}, {...GREY, nm: 1143077999, image: '/images/white/products/p-1143078000-grey-N.jpg', gallery: ['/images/white/products/p-1143078000-grey-b-N.jpg', '/images/white/products/p-1143078000-grey-3-N.jpg', '/images/white/products/p-1143078000-grey-s-N.jpg', '/images/white/products/p-1143078000-grey-d-N.jpg']}], image: '/images/white/products/p-1143078000-N.jpg', nm: 1143078000, gallery: ['/images/white/products/p-1143078000-b-N.jpg', '/images/white/products/p-1143078000-3-N.jpg', '/images/white/products/p-1143078000-s-N.jpg', '/images/white/products/p-1143078000-d-N.jpg']},{key: 11, slug: 'palto-oversayz-s-poyasom', en: 'Long Belted Coat', ru: 'Пальто оверсайз с поясом', cat: 'outerwear', price: 23000, descEn: 'A long oversized demi-season coat with a self-tie belt. Dropped shoulders, a deep collar, floor-skimming.', descRu: 'Длинное оверсайз-пальто демисезона с поясом. Приспущенное плечо, глубокий воротник, длина в пол.', storyEn: 'A long oversized coat with a belt — volume by design rather than by accident. The shoulder is dropped, the collar deep, and the floor-skimming length covers whatever is underneath. Tie the belt and the silhouette gathers at the waist; leave it and the coat reads as a straight robe. Two garments in one. The wool blend is dense, holds warmth and does not let the wind through. Fully lined, with deep pockets. For demi-season and a mild winter: a chunky knit goes under it without any sense of crowding.', storyRu: 'Длинное пальто оверсайз с поясом — тот случай, когда объём задуман, а не случился. Плечо приспущено, воротник глубокий, длина в пол закрывает всё, что надето снизу. Пояс завязывается на талии и собирает силуэт, а без него пальто читается как прямой халат: две вещи в одной. Шерстяная смесь плотная, держит тепло и не продувается на ветру. Полностью на подкладе, карманы глубокие. Демисезон и мягкая зима — под него уходит свитер крупной вязки без чувства тесноты.', compositionEn: 'Wool 60%, cashmere 20%, polyester 15%, viscose 5%', compositionRu: 'Шерсть 60%, кашемир 20%, полиэстер 15%, вискоза 5%', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [{...BROWN, nm: 813600452}, {...BLACK, nm: 100797221, image: '/images/white/products/p-100797221-black-C.jpg', gallery: ['/images/white/products/p-100797221-black-b-C.jpg', '/images/white/products/p-100797221-black-3-C.jpg', '/images/white/products/p-100797221-black-s-C.jpg', '/images/white/products/p-100797221-black-d-C.jpg']}, {...IVORY, nm: 801468660, image: '/images/white/products/p-100797221-ivory-T.jpg', gallery: ['/images/white/products/p-100797221-ivory-b-T.jpg', '/images/white/products/p-100797221-ivory-3-T.jpg', '/images/white/products/p-100797221-ivory-s-T.jpg', '/images/white/products/p-100797221-ivory-d-C.jpg']}, {...CHARCOAL, nm: 814720607, en: 'Brown pinstripe', ru: 'Коричневый в полоску', image: '/images/white/products/p-100797221-stripe-C.jpg', gallery: ['/images/white/products/p-100797221-stripe-b-C.jpg', '/images/white/products/p-100797221-stripe-3-C.jpg', '/images/white/products/p-100797221-stripe-s-C.jpg', '/images/white/products/p-100797221-stripe-d-C.jpg']}], image: '/images/white/products/p-100797221-C.jpg', nm: 813600452, gallery: ['/images/white/products/p-100797221-b-C.jpg', '/images/white/products/p-100797221-3-C.jpg', '/images/white/products/p-100797221-s-C.jpg', '/images/white/products/p-100797221-d-C.jpg']},
  {key: 15, slug: 'palto-kimono-drapovoe', en: 'Draped Kimono Coat', ru: 'Пальто кимоно драповое', cat: 'outerwear', price: 23000, descEn: 'A draped wool kimono coat with a belt and a fluid fall. Heavy wool holds the shape; the silhouette moves with you.', descRu: 'Драповое пальто кимоно с поясом и текучим силуэтом. Плотный драп держит форму, силуэт двигается вместе с вами.', storyEn: 'A draped wool kimono coat with a belt: a wide sleeve, a soft shoulder, a fluid line with no hard edges. The wool is heavy and holds its shape by the weight of the cloth rather than by internal structure, so it settles on the body and falls straight. The belt ties loosely; the length sits at the hip. Warm enough for a real autumn and a mild winter. The kimono cut leaves the shoulders free — an oversized sweater goes underneath without breaking the line.', storyRu: 'Драповое пальто кимоно с поясом: широкий рукав, мягкое плечо, текучий силуэт без жёстких линий. Драп плотный и тяжёлый — он держит форму весом ткани, а не подкладными деталями, поэтому пальто садится по фигуре и падает ровно. Пояс завязывается свободно, длина до бедра. Тепло для настоящей осени и мягкой зимы. Крой кимоно даёт свободу в плечах: под пальто уходит объёмный свитер, и силуэт не ломается.', compositionEn: 'Wool 60%, cashmere 20%, polyester 15%, viscose 5%', compositionRu: 'Шерсть 60%, кашемир 20%, полиэстер 15%, вискоза 5%', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [{...IVORY, nm: 795640219}, {...GREY, nm: 795647903, image: '/images/white/products/p-795640219-grey-Q.jpg', gallery: ['/images/white/products/p-795640219-grey-b-Q.jpg', '/images/white/products/p-795640219-grey-3-Q.jpg', '/images/white/products/p-795640219-grey-s-Q.jpg', '/images/white/products/p-795640219-grey-d-T.jpg']}, {...BROWN, nm: 795627344, image: '/images/white/products/p-795640219-brown-Q.jpg', gallery: ['/images/white/products/p-795640219-brown-b-Q.jpg', '/images/white/products/p-795640219-brown-3-Q.jpg', '/images/white/products/p-795640219-brown-s-Q.jpg', '/images/white/products/p-795640219-brown-d-T.jpg']}], image: '/images/white/products/p-795640219-Q.jpg', nm: 795640219, gallery: ['/images/white/products/p-795640219-b-Q.jpg', '/images/white/products/p-795640219-3-Q.jpg', '/images/white/products/p-795640219-s-Q.jpg', '/images/white/products/p-795640219-d-Q.jpg']},
  {key: 16, slug: 'palto-kimono-korotkoe', en: 'Short Kimono Coat', ru: 'Пальто кимоно короткое', cat: 'outerwear', price: 23000, descEn: 'A cropped kimono coat with clean lines and a soft shoulder. A light top layer with no bulk.', descRu: 'Укороченное пальто кимоно с чистыми линиями и мягким плечом. Лёгкий верхний слой без объёма.', storyEn: 'A cropped kimono coat with clean lines and a soft shoulder. The cut is minimal: a wide armhole, a straight line, a wrap front with no fastening. Hip length — it ends where a skirt or trousers begin and does not cut the figure in half. A mid-weight wool blend for a cool summer and early autumn. This is the finishing layer to an outfit rather than protection from cold: it gives structure to a light dress and gathers a loose bottom half.', storyRu: 'Укороченное пальто кимоно с чистыми линиями и мягким плечом. Крой минимальный: широкая пройма, прямой силуэт, запáх без застёжки. Длина до бедра — пальто заканчивается там, где начинается юбка или брюки, и не перерезает фигуру. Шерстяная смесь средней плотности, для прохладного лета и ранней осени. Это завершающий слой к образу, а не защита от холода: он добавляет структуру лёгкому платью и собирает свободный низ.', compositionEn: 'Wool 60%, cashmere 20%, polyester 15%, viscose 5%', compositionRu: 'Шерсть 60%, кашемир 20%, полиэстер 15%, вискоза 5%', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [{...IVORY, nm: 795670341}, {...GREY, nm: 795657866, image: '/images/white/products/p-795670341-grey-Q.jpg', gallery: ['/images/white/products/p-795670341-grey-3-Q.jpg', '/images/white/products/p-795670341-grey-b-Q.jpg', '/images/white/products/p-795670341-grey-s-Q.jpg', '/images/white/products/p-795670341-grey-d-Q.jpg']}, {...BROWN, nm: 801438197, image: '/images/white/products/p-795670341-brown-T.jpg', gallery: ['/images/white/products/p-795670341-brown-3-T.jpg', '/images/white/products/p-795670341-brown-b-T.jpg', '/images/white/products/p-795670341-brown-s-T.jpg', '/images/white/products/p-795670341-brown-d-Q.jpg']}], image: '/images/white/products/p-795670341-Q.jpg', nm: 795670341, gallery: ['/images/white/products/p-795670341-3-Q.jpg', '/images/white/products/p-795670341-b-Q.jpg', '/images/white/products/p-795670341-s-Q.jpg', '/images/white/products/p-795670341-d-Q.jpg']},
  {key: 18, slug: 'zhilet-s-baskoy-i-kruzhevom', en: 'Lace Peplum Vest', ru: 'Жилет с баской и кружевом', cat: 'tailoring', price: 8000, descEn: 'A tailored peplum vest finished with lace. The sharpness of tailoring, softened at the edge.', descRu: 'Костюмный жилет с баской, завершённый кружевом. Острота тайлоринга, смягчённая по краю.', storyEn: 'A tailored peplum vest finished with lace along the bottom edge. The cut is strict: a structured shoulder, a V-neckline, a four-button front, a waist drawn in with darts. The peplum spreads softly and covers the hip. Scalloped lace runs along the very hem and takes the office dryness out of it — the piece reads as evening while staying tailored in cut. A dense wool blend that holds the shoulder line. Wear it with straight trousers as a suit, with jeans as a contrast, and over a fine roll-neck in winter.', storyRu: 'Костюмный жилет с баской, завершённый кружевом по нижнему краю. Крой строгий: структурное плечо, V-образный вырез, застёжка на четыре пуговицы, талия собрана вытачками. Баска расходится мягко и прикрывает бедро. Кружево с фестонами идёт по самому низу и снимает с жилета офисную сухость — вещь читается вечерней, оставаясь по крою деловой. Шерстяная смесь плотная, держит линию плеча. Носится с прямыми брюками как костюм, с джинсами как контраст и поверх тонкой водолазки зимой.', compositionEn: 'Suiting: polyester 55%, viscose 40%, elastane 5%', compositionRu: 'Костюмная ткань: полиэстер 55%, вискоза 40%, эластан 5%', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [{...BROWN, nm: 1224761706}, {...WHITE_COL, nm: 1224761707, image: '/images/white/products/p-1224761706-white-N.jpg', gallery: ['/images/white/products/p-1224761706-white-b-N.jpg', '/images/white/products/p-1224761706-white-3-N.jpg', '/images/white/products/p-1224761706-white-s-N.jpg', '/images/white/products/p-1224761706-white-d-N.jpg']}, {...BLACK, nm: 1224761708, image: '/images/white/products/p-1224761706-black-N.jpg', gallery: ['/images/white/products/p-1224761706-black-b-N.jpg', '/images/white/products/p-1224761706-black-3-N.jpg', '/images/white/products/p-1224761706-black-s-N.jpg', '/images/white/products/p-1224761706-black-d-N.jpg']}], image: '/images/white/products/p-1224761706-N.jpg', nm: 1224761706, gallery: ['/images/white/products/p-1224761706-b-N.jpg', '/images/white/products/p-1224761706-3-N.jpg', '/images/white/products/p-1224761706-s-N.jpg', '/images/white/products/p-1224761706-d-N.jpg']},
  {key: 19, slug: 'bluzka-shkolnaya-s-volanami', en: 'School Ruffle Blouse', ru: 'Блузка школьная с воланами', cat: 'dresses', price: 6000, descEn: 'An oversized blouse with a wide ruffle across the chest and shoulders. Washed viscose-linen, a soft V neck, lace at the cuff.', descRu: 'Оверсайз-блузка с широким воланом по груди и плечам. Мятая вискоза со льном, мягкий V-вырез, кружево на манжете.', storyEn: 'An oversized blouse built around one gesture: a wide ruffle of the same cloth runs right across the chest and over both shoulders, front and back, falling to about the elbow. Under it the body is generous and the sleeve is full, gathered at the wrist into a narrow cuff with a band of lace at the edge. The neckline is a soft V over a button placket — no collar, nothing to press. The cloth is viscose with linen, the blend sold as French linen: it has the dry crumple of linen without the stiffness, and it moves. School, office or a Saturday, depending on what goes under it.', storyRu: 'Оверсайз-блузка держится на одном приёме: широкий волан из той же ткани идёт через всю грудь и по обоим плечам, спереди и сзади, и падает примерно до локтя. Под ним корпус свободный, рукав объёмный, у запястья собран в узкую манжету с кружевом по краю. Вырез мягкий V на планке — воротника нет, гладить нечего. Ткань — вискоза со льном, та самая смесь, которую продают как французский лён: сухая мятость льна без льняной жёсткости, и она движется. Школа, офис или суббота — зависит от того, что надето снизу.', compositionEn: 'Viscose 70%, linen 30%', compositionRu: 'Вискоза 70%, лён 30%', careEn: 'Machine wash cold, iron up to 150°', careRu: 'Машинная стирка в холодной воде, глажка до 150°', colors: [{...BROWN, nm: 1126294272}, {...IVORY, nm: 1126294270, image: '/images/white/products/p-1126294272-milky-W.jpg', gallery: ['/images/white/products/p-1126294272-milky-b-W.jpg', '/images/white/products/p-1126294272-milky-3-W.jpg', '/images/white/products/p-1126294272-milky-s-W.jpg', '/images/white/products/p-1126294272-milky-d-W.jpg']}, {...WHITE_COL, nm: 1126294269, image: '/images/white/products/p-1126294272-white-W.jpg', gallery: ['/images/white/products/p-1126294272-white-b-W.jpg', '/images/white/products/p-1126294272-white-3-W.jpg', '/images/white/products/p-1126294272-white-s-W.jpg', '/images/white/products/p-1126294272-white-d-W.jpg']}, {...BLACK, nm: 1126294271, image: '/images/white/products/p-1126294272-black-W.jpg', gallery: ['/images/white/products/p-1126294272-black-b-W.jpg', '/images/white/products/p-1126294272-black-3-W.jpg', '/images/white/products/p-1126294272-black-s-W.jpg', '/images/white/products/p-1126294272-black-d-T.jpg']}, {...BORDO, nm: 1126294273, image: '/images/white/products/p-1126294272-bordo-W.jpg', gallery: ['/images/white/products/p-1126294272-bordo-b-W.jpg', '/images/white/products/p-1126294272-bordo-3-W.jpg', '/images/white/products/p-1126294272-bordo-s-W.jpg', '/images/white/products/p-1126294272-bordo-d-W.jpg']}], image: '/images/white/products/p-1126294272-W.jpg', nm: 1126294272, gallery: ['/images/white/products/p-1126294272-b-W.jpg', '/images/white/products/p-1126294272-3-W.jpg', '/images/white/products/p-1126294272-s-W.jpg', '/images/white/products/p-1126294272-d-T.jpg']},
  {key: 20, slug: 'kurtka-bomber-zamsha', en: 'Suede Bomber Jacket', ru: 'Куртка бомбер замша', cat: 'outerwear', price: 50000, season: 'aw26', descEn: 'A bomber in natural suede — a soft collar, an elastic hem, an easy shoulder. Autumn outerwear that asks nothing of you.', descRu: 'Бомбер из натуральной замши — мягкий воротник, резинка по низу, свободное плечо. Осенняя верхняя одежда, которая ничего не требует.', storyEn: 'A bomber cut from natural suede rather than a coating that imitates it — the nap is uneven in the light and the hide softens along the fold lines with wear instead of cracking. The shape is loose: a dropped shoulder, a full sleeve, a shirt collar that stands or falls as you leave it. A seam runs across the chest and the front closes with a concealed zip, so nothing interrupts the surface. Elastic gathers the hem and the cuffs, which is what gives the bomber its shape and keeps the wind out at the waist. Unlined and light for its warmth. It sits over a roll-neck through autumn and takes wide trousers and a straight skirt equally well.', storyRu: 'Бомбер скроен из натуральной замши, а не из покрытия, которое её имитирует: ворс неровно ложится на свету, а кожа по линиям сгиба со временем смягчается, вместо того чтобы трескаться. Силуэт свободный — приспущенное плечо, объёмный рукав, рубашечный воротник, который стоит или падает как оставите. По линии груди идёт шов, застёжка на скрытую молнию, поэтому поверхность ничем не разбита. Резинка собирает низ и манжеты — именно она держит форму бомбера и не пускает ветер по талии. Без подклада и лёгкий для своего тепла. Всю осень садится поверх водолазки, одинаково берёт широкие брюки и прямую юбку.', compositionEn: 'Natural suede', compositionRu: 'Натуральная замша', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [{...BROWN, nm: 1260050013, image: '/images/white/products/p-1260050013-brown-Q.jpg', gallery: ['/images/white/products/p-1260050013-brown-3-Q.jpg', '/images/white/products/p-1260050013-brown-b-Q.jpg', '/images/white/products/p-1260050013-brown-c-Q.jpg', '/images/white/products/p-1260050013-brown-d-Q.jpg']}, {...SAND, nm: 1260050014, image: '/images/white/products/p-1260050013-sand-Q.jpg', gallery: ['/images/white/products/p-1260050013-sand-3-Q.jpg', '/images/white/products/p-1260050013-sand-b-Q.jpg', '/images/white/products/p-1260050013-sand-c-Q.jpg', '/images/white/products/p-1260050013-sand-d-Q.jpg']}, {...GREEN, nm: 1260050015, image: '/images/white/products/p-1260050013-green-Q.jpg', gallery: ['/images/white/products/p-1260050013-green-3-Q.jpg', '/images/white/products/p-1260050013-green-b-Q.jpg', '/images/white/products/p-1260050013-green-c-Q.jpg', '/images/white/products/p-1260050013-green-d-Q.jpg']}], image: '/images/white/products/p-1260050013-brown-Q.jpg', nm: 1260050013, gallery: ['/images/white/products/p-1260050013-brown-3-Q.jpg', '/images/white/products/p-1260050013-brown-b-Q.jpg', '/images/white/products/p-1260050013-brown-c-Q.jpg', '/images/white/products/p-1260050013-brown-d-Q.jpg']},
];

// Editorial imagery — model-on-white shots generated for the White variant (the
// REINASLEO Soul), used for the hero, the atelier/lookbook block and as
// alternate PDP gallery views. Same-origin, so CSP img-src 'self' covers them.
export const WHITE_HERO_IMAGE = '/images/white/hero-mark2.jpg';
export const WHITE_ATELIER_IMAGE = '/images/white/editorial-1.jpg';
export const WHITE_EDITORIAL = ['/images/white/editorial-1.jpg', '/images/white/editorial-2.jpg', '/images/white/editorial-3.jpg'];

export function findWhiteProduct(key?: string | number | null): WhiteProduct | undefined {
  if (key == null) return undefined;
  const k = typeof key === 'string' ? Number.parseInt(key, 10) : key;
  if (Number.isNaN(k)) return undefined;
  return WHITE_PRODUCTS.find((p) => p.key === k);
}

export function findWhiteProductBySlug(slug?: string | null): WhiteProduct | undefined {
  if (!slug) return undefined;
  return WHITE_PRODUCTS.find((p) => p.slug === slug);
}

// Canonical product path. Everything that links to a garment goes through this
// so the slug never has to be assembled by hand at a call site.
export function whiteProductHref(locale: string, product: Pick<WhiteProduct, 'slug'>): string {
  return `/${locale}/product/${product.slug}`;
}

// Nothing here knows what is on the shelf. The catalogue is a static file and
// the real count lives at Wildberries, so the site cannot honestly offer a
// garment for its own bag — it would take an order it may not be able to fill.
// Until stock is wired up (the Ozon integration), every piece reads as
// unavailable and Wildberries is the one route to buying it.
//
// This is the single switch: give it a real source and the whole storefront —
// product page, quick add, markup — starts telling the truth at once.
export function whiteInStock(_product: Pick<WhiteProduct, 'key'>): boolean {
  return false;
}

// Pieces that have gone from the marketplaces too — sold out at Wildberries and
// not on Ozon. They keep their page (the photographs and the search listing are
// worth having) but there is nowhere to send a buyer, so the page offers to take
// a pre-order instead of pretending a route exists. Add a key here when the last
// one leaves the warehouse.
const WHITE_OFF_MARKETPLACES = new Set<number>([]);

// Three honest states, in the order the storefront checks them:
//   'site'        — we hold it and the bag can take it
//   'marketplace' — we do not, but Wildberries or Ozon does
//   'none'        — nowhere; the page offers a pre-order
// Everything that decides between a bag button, a marketplace button and a
// pre-order form reads this one function, so the three can never disagree.
export type WhiteAvailability = 'site' | 'marketplace' | 'none';

export function whiteAvailability(
  product: Pick<WhiteProduct, 'key' | 'nm'>,
  // `onWb` comes from the live marketplace snapshot; it defaults to true so a
  // caller without it keeps the old behaviour of trusting the article number.
  opts?: {onOzon?: boolean; onWb?: boolean},
): WhiteAvailability {
  if (whiteInStock(product)) return 'site';
  if (opts?.onOzon) return 'marketplace';
  const wb = opts?.onWb ?? true;
  if (wb && product.nm && !WHITE_OFF_MARKETPLACES.has(product.key)) return 'marketplace';
  return 'none';
}

export const WHITE_CATS: WhiteCat[] = ['dresses', 'outerwear', 'knitwear', 'tailoring', 'skirts'];

// Single source for the size run, shared by the PDP and the card Quick Add so
// they never drift. Demo sizing — real per-product runs arrive with the catalog.
export const WHITE_SIZES = ['XS', 'S', 'M', 'L', 'XL'] as const;
export type WhiteSize = (typeof WHITE_SIZES)[number];

// Validate a ?cat query value so the shop can be deep-linked/shared. Anything
// unrecognised collapses to 'all' (shared by server page + client showcase).
export function normalizeWhiteCat(value?: string | null): WhiteCat | 'all' {
  return value != null && (WHITE_CATS as string[]).includes(value) ? (value as WhiteCat) : 'all';
}

// Single source of category labels (en/ru), shared by the shop filter chips and
// the server-side <title>, so the two never drift. 'all' is contextual (chip
// reads "All", title reads "Shop"), so each caller supplies that label itself.
const WHITE_CAT_LABELS: Record<WhiteCat, [en: string, ru: string]> = {
  dresses: ['Dresses', 'Платья'],
  outerwear: ['Outerwear', 'Верхняя одежда'],
  knitwear: ['Knitwear', 'Трикотаж'],
  tailoring: ['Tailoring', 'Костюмы'],
  skirts: ['Skirts', 'Юбки'],
};
export function whiteCatLabel(cat: WhiteCat, locale: string): string {
  const [en, ru] = WHITE_CAT_LABELS[cat];
  return locale === 'ru' ? ru : en;
}

// Curated sets — looks assembled from the real catalogue, sold together or
// piece by piece. The image is the set's editorial mood; the items below it
// are the actual products (each with its own card and sizes).
export type WhiteSet = {
  key: string;
  en: string;
  ru: string;
  descEn: string;
  descRu: string;
  image: string;
  productKeys: number[];
  // Which colour of each garment is the one actually worn in the photograph,
  // keyed by product. Without it the cards fall back to a product's first
  // colour, so a look shot in a brown coat and a sand skirt was listed as a
  // black coat and a black skirt — the same two garments, but not this outfit.
  // Only needed where the set differs from the default; omit and the default
  // is right.
  colours?: Record<number, string>;
};

